export type DispatchRecord = {
  id: number;
  operator: string;
  destination: string;
  priority: number;
};

function assertRecord(value: unknown): asserts value is DispatchRecord {
  if (typeof value !== "object" || value === null) throw new TypeError("Invalid record");
  const record = value as Record<string, unknown>;
  if (!Number.isInteger(record.id) || typeof record.operator !== "string" ||
      typeof record.destination !== "string" || typeof record.priority !== "number" ||
      !Number.isFinite(record.priority)) {
    throw new TypeError("Invalid record");
  }
}

export function selectDispatches(
  records: readonly DispatchRecord[],
  operator: string
): DispatchRecord[] {
  if (!Array.isArray(records) || typeof operator !== "string") {
    throw new TypeError("Invalid arguments");
  }
  for (const record of records) assertRecord(record);
  return records.filter(record => record.operator === operator);
}

