import { selectDispatches, type DispatchRecord } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: ${JSON.stringify(actual)}`);
  }
}
function throwsTypeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const records: DispatchRecord[] = [
  { id: 1, operator: 'Alpha', destination: 'North', priority: 1 },
  { id: 2, operator: 'alpha', destination: 'South', priority: 2.5 },
  { id: 3, operator: 'Alpha', destination: 'West', priority: -4 }
];
const selected = selectDispatches(records, 'Alpha');
deepEqual(selected, [records[0], records[2]], 'matches exactly and preserves order');
assert(selected !== records, 'result array is fresh');
assert(selected[0] !== records[0] && selected[1] !== records[2], 'records are copied');
selected[0].destination = 'Changed';
selected.push({ id: 9, operator: 'Alpha', destination: 'Extra', priority: 0 });
assert(records[0].destination === 'North' && records.length === 3, 'result mutation does not affect input');

deepEqual(selectDispatches(records, ' alpha '), [], 'operator is not trimmed');
deepEqual(selectDispatches([], 'Alpha'), [], 'empty input returns empty array');
deepEqual(selectDispatches(records, 'Missing'), [], 'no match returns empty array');
deepEqual(records, [
  { id: 1, operator: 'Alpha', destination: 'North', priority: 1 },
  { id: 2, operator: 'alpha', destination: 'South', priority: 2.5 },
  { id: 3, operator: 'Alpha', destination: 'West', priority: -4 }
], 'input is not mutated');

throwsTypeError(() => selectDispatches({} as unknown as DispatchRecord[], 'Alpha'), 'non-array records rejected');
throwsTypeError(() => selectDispatches(records, 1 as unknown as string), 'non-string operator rejected');
throwsTypeError(() => selectDispatches([{ id: 1.2, operator: 'Alpha', destination: 'X', priority: 1 }], 'Alpha'), 'fractional id rejected');
throwsTypeError(() => selectDispatches([{ id: 1, operator: 7 as unknown as string, destination: 'X', priority: 1 }], 'Alpha'), 'non-string record operator rejected');
throwsTypeError(() => selectDispatches([{ id: 1, operator: 'Alpha', destination: null as unknown as string, priority: 1 }], 'Alpha'), 'non-string destination rejected');
throwsTypeError(() => selectDispatches([{ id: 1, operator: 'Alpha', destination: 'X', priority: Infinity }], 'Alpha'), 'infinite priority rejected');
throwsTypeError(() => selectDispatches([
  { id: 1, operator: 'Alpha', destination: 'X', priority: 1 },
  { id: 2, operator: 'Other', destination: 'Y', priority: NaN }
], 'Alpha'), 'unmatched records are validated');

